import java.util.*;
public class Main {
    static class Node {
        int data;
        Node next;
        Node(int data) { this.data = data; }
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        Node[] nodes = new Node[n];
        for (int i = 0; i < n; i++) {
            nodes[i] = new Node(sc.nextInt());
        }
        int pos = sc.nextInt();
        Node head = n == 0 ? null : nodes[0];
        for (int i = 0; i + 1 < n; i++) {
            nodes[i].next = nodes[i + 1];
        }
        if (n > 0 && pos > 0) {
            nodes[n - 1].next = nodes[pos - 1];
        }
        Node slow = head;
        Node fast = head;
        boolean cycle = false;
        while (fast != null && fast.next != null) {
            slow = slow.next;
            fast = fast.next.next;
            if (slow != null && fast != null && slow.data == fast.data) {
                cycle = true;
                break;
            }
        }
        System.out.println(cycle ? "Cycle" : "No Cycle");
        sc.close();
    }
}
